  ["SWITZERLAND"] = "ELVEȚIA",
  ["Spring back out of distance. Escapes a slow riposte, rarely a direct one."] = "Revii în gardă, din distanță. Scapi de riposta lentă, rar de cea directă.",
  ["Stay in the lunge and put the point back. It only scores against a slow riposte."] = "Rămâi în fandare și repui vârful. Contează doar contra unei riposte lente.",
  ["Straight back at once: it beats a remise. A counter-parry can stop it."] = "Imediat și direct: bate remiza. O contraparadă o poate opri.",
  ["Sweep a full circle: catches a disengage. A little slower against a direct attack."] = "Un cerc complet: prinde degajamentul. Puțin mai lentă contra atacului direct.",
